/// The auth-expired surface body (card AND the chat's error banner,
/// The host-quota marker link (gh-2391): the HTTPS url inside
/// `[[host-quota:<url>]]`, or null (absent / non-HTTPS — never opened).
Uri? hostQuotaLinkFrom(String content) {
  const prefix = '[[host-quota:';
  final start = content.indexOf(prefix);
  if (start < 0) return null;
  final end = content.indexOf(']]', start + prefix.length);
  if (end < 0) return null;
  final raw = content.substring(start + prefix.length, end).trim();
  if (raw.isEmpty) return null;
  final uri = Uri.tryParse(raw);
  if (uri == null || uri.scheme != 'https' || uri.host.isEmpty) return null;
  return uri;
}

/// Removes the host-quota marker (and surrounding whitespace).
String stripHostQuotaMarker(String content) =>
    content.replaceAll(RegExp(r'\[\[host-quota:[^\]]*\]\]'), '').trim();

/// The auth-expired display text (issue #692): the raw provider error
/// minus the `[[auth-expired:…]]` marker and any `(CLI: …)` recovery
/// hint. The CLI instruction is dead text on app hosts
/// (mobile/desktop/overlay), where the surface's own Authorize button is
/// the actionable path.
String authExpiredDisplayText(String content) {
  var text = stripAuthExpiredMarker(content);
  text = text.replaceAll(RegExp(r'\s*\(CLI:[^)]*\)'), '');
  return text.trim();
}

/// Tool-output block that caps long dumps (file reads, big writes) at a
/// three-line preview with an inline expand/collapse toggle (issue #458) —
/// the transcript stays scannable while the full output remains one tap
/// away. Failed results start expanded (errors are why you look) with a
/// tighter scroll cap; the expanded/collapsed choice is per-card and
/// never persisted.
class _CollapsibleToolOutput extends StatefulWidget {
  const _CollapsibleToolOutput({
    required this.content,
    required this.style,
    this.showTail = false,
    this.initiallyExpanded = false,

    // Issue #327: provider auth failures surface the owning row's name —
    // a bare `401: No cookie auth credentials found` gives the user no
    // idea WHICH provider row to fix. On-device bridges keep raw errors.
    String? Function() rowLabel = () => _connectionDisplayName(
      _providerRegistry,
      config.baseUrl,
    ); // null = pass-through, no registry row to name.
    // The bare provider stream — the host decorator must see the RAW
    // error text (leading `NNN:` status + structured rate-limit info);
    // the row-label auth decoration wraps it from OUTSIDE so a passed-
    // through failure still names the row.
    StreamFunction providerFor(String key) => providerStreamFunction(
      config.providerKind,
      key,
      sessionId: () => _session?.cachedId,
    );
    // The host-session seam (gh-2391): requests riding the host entry get
    // the quota notice + one silent bridge re-resolution. Non-host (and
    // stock) connections keep the exact pre-2391 stream shape.
    if (!HostSessionHandle.instance.serves(config.baseUrl)) {
      return decorateAuthErrors(providerFor(apiKey), rowLabel);
    }
    return decorateAuthErrors(
      decorateHostSession(
        providerFor(apiKey),
        config,
        rebuildWithKey: providerFor,
      ),
      rowLabel,
    );
  }

