const hostQuotaMarkerPrefix = '[[host-quota:';

/// The quota notice suffix when the profile declares no link.
const hostQuotaMarkerNoLink = '[[host-quota:]]';

/// Builds the marker for a validated profile [HostQuotaConfig].
